"""Random threshold pairs and reading streams, including runs that hover
inside the dead zone on purpose."""


def generate(rng, count):
    builders = (_random_walk, _dead_zone_hover, _clean_crossings)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, state, low, high, readings, description=""):
    lines = ["%d %d %d" % (state, low, high)]
    lines.extend(str(r) for r in readings)
    return {"name": name, "stdin": "\n".join(lines) + "\n",
            "description": description}


def _random_walk(rng, index):
    low, high = 20, 80
    readings = [rng.randint(0, 100) for _ in range(8)]
    return _case("a random signal #%d" % index, 0, low, high, readings)


def _dead_zone_hover(rng, index):
    low, high = 20, 80
    readings = [rng.randint(low + 1, high - 1) for _ in range(6)]
    return _case("hovering entirely inside the dead zone #%d" % index,
                 rng.choice((0, 1)), low, high, readings,
                 "Every reading is strictly between low and high -- the "
                 "state must never move.")


def _clean_crossings(rng, index):
    low, high = 10, 90
    readings = [5, 95, 5, 95, 5]
    return _case("clean crossings, alternating #%d" % index, 0, low, high,
                 readings)
